export type CommitHash = string;

/**  One encoded commit, for sending to another replica (e.g. via subduction). */
export type Fragment = {
	hash: CommitHash,
	parents: CommitHash[],
	bytes: Uint8Array,
};

export type Path = string;

/**  A temporary row ID that is valid only within a transaction. */
export type PendingRowId = number;

/**
 *  The unique id that identifies each row in a table.
 * 
 *  It is managed by the database and read-only for the user.
 */
export type PublicRowId = {
	commit: CommitHash,
	counter: number,
};

/**
 * The scalars crossing the public (FFI) boundary: exactly the column types a Coln program can declare.
 * 
 * There are no 64-bit integers, so every value round-trips through a JS `number` without precision loss. That also makes the untagged encoding unambiguous: a row id is an object, an `I32` a number and a `String` a string. Adding another integer type would require deserializing against the column types instead.
 */
export type PublicScalar<RowId, I32 = number, String = string> = RowId | I32 | String;

/**
 *  A public facing value, consumed by the FFI/user, where the row_ids are resolved
 *  to be (hash, counter)
 */
export type PublicTuple = Tuple<PublicScalar<PublicRowId, number, string>>;

export type Tuple<ScalarValue> = ScalarValue[];

/**  Its difference with a pure WireRowId is that it can be a pending id */
export type TxRowId = { type: "Existing"; value: PublicRowId } | { type: "Pending"; value: PendingRowId };

export type TxTuple = Tuple<PublicScalar<TxRowId, number, string>>;

export type WhereClause = {
	table_name: Path,
	row_id: PublicRowId | null,
	values: PublicTuple,
};
